python3 - <<'EOF'
import re, pandas as pd, sys
sys.path.insert(0,'tests'); from test_sarcasm import SARCASTIC_NEGATIVE as S
syn=" ".join(pd.read_csv('synthetic.csv').text).lower()
toks=lambda t: re.findall(r"[a-z']+", t.lower())
st=toks(syn); grams=set(tuple(st[i:i+4]) for i in range(len(st)-3))
for s in S:
    t=toks(s); hits={" ".join(t[i:i+4]) for i in range(len(t)-3) if tuple(t[i:i+4]) in grams}
    if hits: print(hits, '|', s[:60])
EOF
